WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_age_mp_three'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '三人年龄关系', 'kp-age-mp-three', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "三人年龄关系"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "甲比乙大，乙比丙大。中间人是天然的桥梁。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“甲乙丙三人，甲今年是丙的3倍，乙比丙大5岁……”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心破题：设最小值为 x"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "遇到三个人的串联关系，永远设年龄最小的那个人为 x（或者设处于逻辑最末端的那个）。这样可以保证所有人都能用含有 x 的正整数或加法式子表示出来，避免出现繁分数或减法。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[阅读三人关系] --> B[找出其中被比较最多、或者年龄最小的人]\nB --> C[令他为 x]\nC --> D[用 x 将另外两人的年龄正向推导出来]\nD --> E[利用最后一个条件(如三人总和)建立大等式求解]"}}]}$$ AS jsonb), NULL, '三人年龄关系的核心考点与实战推导。', category_node.id, CAST('["数量关系", "年龄问题", "三人年龄关系"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_age_mp_three", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
